	attribute rom_style : string;
	attribute rom_style of M_TAB : constant is "block";

type ALUCtrl_t is array(0 to 16) of ALUCtrl_r;
	constant ALU_TAB: ALUCtrl_t := (
	("100","100",'0','0'),-- 00000 LOAD 8BIT
	("100","100",'0','1'),-- 00001 LOAD 16BIT
	("110","100",'0','0'),-- 00010 DEC 
	("111","100",'0','0'),-- 00011 INC
	("100","000",'0','0'),-- 00100 ORA
	("100","001",'0','0'),-- 00101 AND
	("100","010",'0','0'),-- 00110 EOR
	("100","011",'0','0'),-- 00111 ADC
	("100","111",'1','0'),-- 01000 SBC
	("100","001",'1','0'),-- 01001 BIT
	("000","100",'0','0'),-- 01010 ASL
	("010","100",'0','0'),-- 01011 LSR
	("001","100",'0','0'),-- 01100 ROL
	("011","100",'0','0'),-- 01101 ROR
	("100","101",'0','0'),-- 01110 TRB
	("100","101",'1','0'),-- 01111 TSB
	("100","110",'0','0') -- 10000 CMP
	);

	constant FETCH : std_logic_vector(52 downto 0) := "00000000000000000000000000100000000000000000000000011";
	signal MI      : MicroInst_r;
	signal MIV     : std_logic_vector(52 downto 0);
	signal ROMQ    : std_logic_vector(52 downto 0);
	signal ST0     : std_logic;
	signal STATE2  : unsigned(3 downto 0);
	signal ALUFlags : ALUCtrl_r;

begin

	ALUFlags <= ALU_TAB(to_integer(unsigned(MI.ALUCtrl)));
	STATE2 <= STATE - 1;

	-- the table is read into a register without a reset (a block RAM has none); ST0 says that the row of the last cycle is the fetch row
	process(CLK)
	begin
		if rising_edge(CLK) then
			if EN = '1' then
				ROMQ <= M_TAB(to_integer(unsigned(IR) & STATE2(2 downto 0)));
			end if;
		end if;
	end process;

	process(CLK, RST_N)
	begin
		if RST_N = '0' then
			ST0 <= '1';
		elsif rising_edge(CLK) then
			if EN = '1' then
				if STATE = "0000" then ST0 <= '1'; else ST0 <= '0'; end if;
			end if;
		end if;
	end process;

	MIV <= FETCH when ST0 = '1' else ROMQ;
	MI.stateCtrl <= MIV(52 downto 50);
	MI.addrBus <= MIV(49 downto 46);
	MI.addrInc <= MIV(45 downto 44);
	MI.loadP <= MIV(43 downto 41);
	MI.loadT <= MIV(40 downto 39);
	MI.muxCtrl <= MIV(38 downto 37);
	MI.addrCtrl <= MIV(36 downto 29);
	MI.loadPC <= MIV(28 downto 26);
	MI.loadSP <= MIV(25 downto 23);
	MI.regAXY <= MIV(22 downto 20);
	MI.loadDKB <= MIV(19 downto 18);
	MI.busCtrl <= MIV(17 downto 12);
	MI.ALUCtrl <= MIV(11 downto 7);
	MI.byteSel <= MIV(6 downto 5);
	MI.outBus <= MIV(4 downto 2);
	MI.va <= MIV(1 downto 0);

	M <= (ALUFlags, MI.stateCtrl, MI.addrBus, MI.addrInc, MI.muxCtrl, MI.addrCtrl, MI.loadPC, MI.loadSP,
			MI.regAXY, MI.loadP, MI.loadT, MI.loadDKB, MI.busCtrl, MI.byteSel, MI.outBus, MI.va);

end rtl;
